const wordEl = root.querySelector('.m-mht-word');
const words = ['HYPER TEXT', 'MOTION SPEC', 'EASE CURVE'];
const ABC = 'ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789';
let idx = 0, raf = 0, timer = 0, lastTick = 0;

function run(target) {
  cancelAnimationFrame(raf);
  const start = performance.now();
  lastTick = 0;
  function step(now) {
    if (!root.isConnected) return;
    const p = Math.min(1, (now - start) / 800);
    if (p >= 1 || now - lastTick >= 32) {
      lastTick = now;
      const locked = Math.floor(p * target.length);
      let out = '';
      for (let i = 0; i < target.length; i++) {
        out += target[i] === ' ' ? ' ' : (i < locked ? target[i] : ABC[(Math.random() * ABC.length) | 0]);
      }
      wordEl.textContent = out;
    }
    if (p < 1) raf = requestAnimationFrame(step);
  }
  raf = requestAnimationFrame(step);
}

const trigger = () => { idx = (idx + 1) % words.length; run(words[idx]); };
root.addEventListener('pointerenter', trigger);
root.addEventListener('click', trigger);
run(words[0]);
timer = setInterval(trigger, 3200);
return () => {
  cancelAnimationFrame(raf);
  clearInterval(timer);
  root.removeEventListener('pointerenter', trigger);
  root.removeEventListener('click', trigger);
};

