const uid = 'mmt-' + Math.random().toString(36).slice(2, 8);
const flt = root.querySelector('.m-mmt-filter');
const stg = root.querySelector('.m-mmt-stage');
flt.id = uid;
stg.style.filter = `url(#${uid}) blur(0.4px)`;
const a = root.querySelector('.m-mmt-a');
const b = root.querySelector('.m-mmt-b');
const words = ['Kinetic', 'Elastic', 'Tactile', 'Fluid'];
let idx = 0, morph = 0, cool = 0.75, last = performance.now(), raf = 0;
const MORPH_T = 1.45, COOL_T = 0.85;

function setTexts() {
  a.textContent = words[idx % words.length];
  b.textContent = words[(idx + 1) % words.length];
}
setTexts();

function applyMorph(f) {
  const c = Math.max(0.001, Math.min(0.999, f));
  b.style.filter = `blur(${Math.min(8 / c - 8, 100).toFixed(2)}px)`;
  b.style.opacity = Math.pow(c, 0.4).toFixed(3);
  const inv = 1 - c;
  a.style.filter = `blur(${Math.min(8 / inv - 8, 100).toFixed(2)}px)`;
  a.style.opacity = Math.pow(inv, 0.4).toFixed(3);
}

function tick(now) {
  if (!root.isConnected) return;
  const dt = Math.min(0.05, (now - last) / 1000);
  last = now;
  if (cool > 0) {
    cool -= dt;
    b.style.filter = ''; b.style.opacity = '1';
    a.style.filter = ''; a.style.opacity = '0';
    if (cool <= 0) { idx = (idx + 1) % words.length; setTexts(); morph = 0; }
  } else {
    morph += dt;
    const f = morph / MORPH_T;
    if (f >= 1) { cool = COOL_T; }
    else applyMorph(f);
  }
  raf = requestAnimationFrame(tick);
}
const onClick = () => { cool = 0; idx = (idx + 1) % words.length; setTexts(); morph = 0; };
root.addEventListener('click', onClick);
raf = requestAnimationFrame(tick);
return () => { cancelAnimationFrame(raf); root.removeEventListener('click', onClick); };

