const bar = root.querySelector('.m-mmd-bar');
const items = [...root.querySelectorAll('.m-mmd-item')];
const st = items.map(() => ({ s: 34, v: 0 }));
let pointerX = null, raf = 0, last = performance.now();

const onMove = e => { pointerX = e.clientX; };
const onLeave = () => { pointerX = null; };
root.addEventListener('pointermove', onMove);
root.addEventListener('pointerleave', onLeave);

function tick(now) {
  if (!root.isConnected) return;
  const dt = Math.min(0.032, (now - last) / 1000);
  last = now;
  const rect = bar.getBoundingClientRect();
  const autoX = rect.left + rect.width * (0.5 + 0.44 * Math.sin(now * 0.0014));
  const mx = pointerX !== null ? pointerX : autoX;

  items.forEach((el, i) => {
    const r = el.getBoundingClientRect();
    const cx = r.left + r.width * 0.5;
    const dist = Math.abs(mx - cx);
    const infl = dist < 84 ? 0.5 * (1 + Math.cos(Math.PI * dist / 84)) : 0;
    const target = 34 + infl * 22;
    const f = 240 * (target - st[i].s) - 18 * st[i].v;
    st[i].v += f * dt;
    st[i].s += st[i].v * dt;
    const sz = st[i].s.toFixed(2) + 'px';
    el.style.width = sz;
    el.style.height = sz;
    el.style.fontSize = (13 + infl * 6).toFixed(1) + 'px';
  });
  raf = requestAnimationFrame(tick);
}
