const canvas = root.querySelector('.m-rcs-c');
const ctx = canvas.getContext('2d');
const palette = ['#ffffff', '#38bdf8', '#f472b6', '#fbbf24'];
const bursts = [];
let raf = 0, lastAuto = 0, userClicked = false;

function spawn(x, y) {
  const color = palette[bursts.length % palette.length];
  const count = 10;
  const rot = Math.random() * 0.4;
  bursts.push({ x, y, t0: performance.now(), color, count, rot });
  if (bursts.length > 24) bursts.shift();
}

const onDown = e => {
  userClicked = true;
  const r = canvas.getBoundingClientRect();
  spawn(e.clientX - r.left, e.clientY - r.top);
};
root.addEventListener('pointerdown', onDown);

function tick(now) {
  if (!root.isConnected) return;
  const dpr = Math.min(2, window.devicePixelRatio || 1);
  const w = canvas.clientWidth || 320, h = canvas.clientHeight || 240;
  if (canvas.width !== Math.round(w * dpr) || canvas.height !== Math.round(h * dpr)) {
    canvas.width = Math.round(w * dpr); canvas.height = Math.round(h * dpr);
  }
  ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
  ctx.clearRect(0, 0, w, h);

  if (!userClicked && now - lastAuto > 1250) {
    lastAuto = now;
    spawn(w * (0.25 + Math.random() * 0.5), h * (0.28 + Math.random() * 0.44));
  }

  for (let b = bursts.length - 1; b >= 0; b--) {
    const item = bursts[b];
    const t = (now - item.t0) / 480;
    if (t < 0) continue;
    if (t >= 1) { bursts.splice(b, 1); continue; }
    const e = 1 - Math.pow(1 - t, 3);
    const dist = e * 44;
    const len = 16 * (1 - e);
    ctx.strokeStyle = item.color;
    ctx.globalAlpha = Math.max(0, 1 - t * 0.9);
    ctx.lineWidth = 2;
    ctx.lineCap = 'round';
    for (let i = 0; i < item.count; i++) {
      const a = item.rot + (i * Math.PI * 2) / item.count;
      ctx.beginPath();
      ctx.moveTo(item.x + Math.cos(a) * dist, item.y + Math.sin(a) * dist);
      ctx.lineTo(item.x + Math.cos(a) * (dist + len), item.y + Math.sin(a) * (dist + len));
      ctx.stroke();
    }
    ctx.beginPath();
    ctx.globalAlpha = (1 - t) * 0.25;
    ctx.lineWidth = 1;
    ctx.arc(item.x, item.y, e * 32, 0, Math.PI * 2);
    ctx.stroke();
  }
  ctx.globalAlpha = 1;
  raf = requestAnimationFrame(tick);
}
raf = requestAnimationFrame(tick);
return () => { cancelAnimationFrame(raf); root.removeEventListener('pointerdown', onDown); };

